-- Import of «Արարատ խաղալիք Ֆինալ.xlsx» into the business of karlen.sargsian.98@gmail.com ONLY.
-- Generated automatically. Runs as one transaction: if any check fails, nothing is saved.
-- It refuses to run twice (stops if this business already has imported orders).
begin;

create temp table import_target on commit drop as
  select t.id as tenant_id from public.tenants t
  join auth.users u on u.id = t.owner_id
  where lower(u.email) = 'karlen.sargsian.98@gmail.com';

do $$
begin
  if (select count(*) from import_target) <> 1 then
    raise exception 'Business of karlen.sargsian.98@gmail.com not found';
  end if;
  if exists (select 1 from public.orders o join import_target t using (tenant_id)
             where o.metadata ? 'sheet_order_id') then
    raise exception 'This sheet was already imported';
  end if;
  if (select count(*) from public.products p join import_target t using (tenant_id)
      where p.title in ('Մեծ Արարատ 70սմ', 'Փոքր Արարատ 45սմ', 'Դեդո-Բաբո')) <> 3 then
    raise exception 'Expected products Մեծ Արարատ 70սմ, Փոքր Արարատ 45սմ, Դեդո-Բաբո';
  end if;
end $$;

-- ── Order source used in the sheet ───────────────────────────
