-- ── Reinvestments (6) ──
insert into public.reinvestments (tenant_id, product_id, purpose, amount, status, invest_date)
select t.tenant_id, p.id, v.purpose, v.amount, v.status, v.d::date
from import_target t
cross join (values
  ('2026-07-15', 'Նոր ապրանքի պատվեր — Դեդո Բաբո — 100 հատ', 615000.0, 'Դեդո-Բաբո', 'done'),
