-- ── Warehouse: gifts from the «Նվերներ» tab; current stock minus those gifts ──
update public.inventory i set gift_quantity = 17, stock_quantity = greatest(stock_quantity - 17, 0), updated_at = now()
from public.products p, import_target t
where i.product_id = p.id and p.tenant_id = t.tenant_id and p.title = 'Փոքր Արարատ 45սմ';
update public.inventory i set gift_quantity = 9, stock_quantity = greatest(stock_quantity - 9, 0), updated_at = now()
from public.products p, import_target t
where i.product_id = p.id and p.tenant_id = t.tenant_id and p.title = 'Մեծ Արարատ 70սմ';

-- ── Checks: totals must match the sheet ──
do $$
declare v_orders int; v_total numeric; v_exp numeric;
begin
  select count(*), sum(order_total) into v_orders, v_total
  from public.orders o join import_target t using (tenant_id) where o.metadata ? 'sheet_order_id';
  select sum(amount) into v_exp from public.expenses e join import_target t using (tenant_id);
  if v_orders <> 231 then raise exception 'orders: expected 231, got %', v_orders; end if;
  if v_total <> 3250428.0 then raise exception 'order total: expected 3250428.0, got %', v_total; end if;
  if v_exp < 1418000.0 then raise exception 'expenses total mismatch: %', v_exp; end if;
end $$;

commit;
